using System;
using System.Collections.Generic;
using System.Collections.Immutable;
using System.Linq;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using ConsoleTables;
using Extensions.Pack;
using AspNetCore.MinimalApi.Sdk.CodeRules.Api.Controllers;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("API - Controllers")]
    [TestClass]
    public class RJIT_CR_API_C_00026 : ControllerTestBase
    {
        private Regex UrlParameterRegex = new Regex("(?<=\\{)(.*?)(?=\\})");

         [TestMethod]
        public void Methods_Should_Declare_All_Route_Parameter_As_Method_Parameters()
        {
            var missingUrlParameters = FindMissingUrlParameterUsages().ToImmutableList();

            Assert.IsTrue(missingUrlParameters.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_API_C_00026

Missing url parameter detected.: {Environment.NewLine}{missingUrlParameters.Flatten(Environment.NewLine)}{Environment.NewLine}");


            IEnumerable<string> FindMissingUrlParameterUsages()
            {
                foreach (var controller in Controllers)
                {
                    var routes = controller.Attributes.Where(a => a.Name.StartWith("Route")).ToImmutableList();
                    var urlParameters = routes.SelectMany(r => r.Arguments).Distinct().ToImmutableList();
                    var parameterNames = urlParameters.Select(argument => UrlParameterRegex.Matches(argument))
                                                      .SelectMany(matchCollection => matchCollection)
                                                      .Select(match => match.Value)
                                                      .Where(param => param.DoesNotContain("apiVersion"))
                                                      .Distinct()
                                                      .ToImmutableList();

                    foreach (var controllerMethod in controller.Methods)
                    {
                        var httpActions = controllerMethod.Attributes.Where(a => a.Name.StartWith("Http")).ToImmutableList();
                        var urlParametersFromHttpAction = httpActions.SelectMany(r => r.Arguments).Distinct().ToImmutableList();
                        var httpActionParmater = urlParametersFromHttpAction.Select(argument => UrlParameterRegex.Matches(argument))
                                                                            .SelectMany(matchCollection => matchCollection)
                                                                            .Select(match => match.Value)
                                                                            .Distinct()
                                                                            .ToImmutableList();

                        var route = $"{routes.FirstOrDefault()?.Arguments.Flatten()}/{httpActions.FirstOrDefault()?.Arguments.Flatten()}";
                        route = route.Replace("\"", string.Empty);
                        var allParameters = parameterNames.Concat(httpActionParmater).ToImmutableList();
                        var missingParameters = allParameters.Except(controllerMethod.Parameters, p => p, p => p.Name).ToImmutableList();
                        var methodParametersAsString = missingParameters.Select(m => $"object {m}, ").Flatten();
                        if (missingParameters.Any())
                        {
                            yield return $@"
Your method: {controllerMethod.Name} does not declare all needed parameter from your url route !
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Controller:  {controller.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Route:       {route}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Missing:     {missingParameters.Flatten(", ")}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Method:      

{controllerMethod.MethodValue.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:      

{controllerMethod.MethodValue.Replace($"{controllerMethod.Name}(", $"{controllerMethod.Name}({methodParametersAsString}").FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
";
                        }
                    }
                }
            }
        }
    }
}
